import{_ as t,H as a,f as o,i as _}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"新书首发 | 《硅谷产品：36讲直通世界级产品经理》","description":"","frontmatter":{},"headers":[],"relativePath":"硅谷产品实战36讲/新书首发-《硅谷产品：36讲直通世界级产品经理》.md","filePath":"硅谷产品实战36讲/新书首发-《硅谷产品：36讲直通世界级产品经理》.md","lastUpdated":1779821454000}'),p={name:"硅谷产品实战36讲/新书首发-《硅谷产品：36讲直通世界级产品经理》.md"};function r(s,e,n,i,l,c){return a(),o("div",null,[...e[0]||(e[0]=[_('<h1 id="新书首发-《硅谷产品-36讲直通世界级产品经理》" tabindex="-1">新书首发 | 《硅谷产品：36讲直通世界级产品经理》 <a class="header-anchor" href="#新书首发-《硅谷产品-36讲直通世界级产品经理》" aria-label="Permalink to &quot;新书首发 | 《硅谷产品：36讲直通世界级产品经理》&quot;">​</a></h1><p>你好，我是曲晓音。在专栏更新完最后一篇文章的三个月时间后，我要再和你分享一个好消息。今天，我的新书在极客商城上架了，书名叫《硅谷产品：36讲直通世界级产品经理》。</p><p>很多老朋友可能会问我，出了专栏为什么还要出书？</p><p>其实，从2018年春节“极客时间”的编辑找到我，到7月14号专栏内容全部更新结束，这半年多的时间里，我在专栏写作、回复你的留言，以及寻思你可能遇到的产品相关问题的过程中，也在不断梳理、迭代自己这些年在硅谷做产品经理的所思、所感、所悟。当然了，我非常希望能把这些内容固化下来，不仅仅是作为你闲时的消遣，而是能真正帮你解决在产品路上遇到的各种问题。</p><p>同时，这半年来，和专栏编辑、图书编辑磨稿的过程中，我最深的感触是，专栏和图书是不一样的。专栏是文字+音频的形式，更适合通勤路上等更碎片化、更适合“听”的场景；而纸质图书，更适合你慢慢琢磨其中的内容。因此，这也就决定了 <strong>专栏和图书在内容交付上是不一样的，也因此有了今天这本书的问世</strong>。</p><p>在图书出版的过程中，我和编辑又根据纸质图书的特点，在专栏文章的基础上进行了些调整，比如我又优化了一部分文章的结构脉络，旨在帮助你通过图书 +专栏的形式，充实自己的碎片化时间，梳理出更高效的学习路径，锤炼自己的产品思维。</p><p>说到底，这些优化，很多是源自于你在专栏文章下的高质量留言。可以说，是你的赞赏、批评等各种支持，帮助我一起创作了这本书。</p><p>所以，如果你想系统、全面地了解产品经理这个行业，也想看看硅谷的产品经理从0到1打造一个千万用户级产品的过程，那么这本书将是一个不错的选择。正如《人人都是产品经理》的作者苏杰为这本书写的推荐语：</p><blockquote><p>国内写产品经理的书有很多，我们引进的硅谷相关图书也不可谓少，但本书是一个在Facebook等硅谷科技公司工作过的中国人，用她的双重视角写出的。内容方面，既走在行业前沿，又可落地操作，相信对各位同行会有很大帮助。</p></blockquote><p>最后，能出版这样一本书，我感到很荣幸，也非常珍惜能把我这些年的思考和体验提炼成文字的机会，通过这种方式和你聊聊天。同时，我也很感激这几个月以来有你的陪伴。如果你在阅读这本书的过程中，有任何的问题、困惑，都可以在专栏对应文章下，给我留言，我将时不时地回来看看，和你分享我最新的想法。</p><p>《硅谷产品》这本书已经在极客商城提前开售，作为已经订阅专栏的老朋友，除了首发优惠之外，我还给你申请了优惠码。在极客商城待付款订单中点击“使用优惠”，输入优惠码“chanpin”，结算时可再减5元。</p><p>最后，希望你也能找到属于自己的“灯塔”，亲手设计出那款世界级的产品。</p><p><a href="time://mall?url=https%3A%2F%2Fdetail.youzan.com%2Fshow%2Fgoods%3Falias%3D2fxu3d5fmo388%26dc_ps%3D2101180398909261828.200001" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A1%85%E8%B0%B7%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%9836%E8%AE%B2/images/41826/f41f1254d4a091a675fe8c3fe77df5b9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%A1%85%E8%B0%B7%E4%BA%A7%E5%93%81%E5%AE%9E%E6%88%9836%E8%AE%B2/images/41826/f41f1254d4a091a675fe8c3fe77df5b9.jpg" alt="unpreview"></a></a></p>',13)])])}const E=t(p,[["render",r]]);export{d as __pageData,E as default};
